// Shapes of the JSON files in public/data. They are generated by the archive
// repository (python -m src.rebuild); see docs/DATA.md there for definitions.

/** public/data/index.json */
export type LeagueIndex = {
  leagueId: string;
  leagueName: string;
  provider: string;
  firstSeason: number;
  lastSeason: number;
  seasonCount: number;
  seasons: SeasonSummary[];
};

export type SeasonSummary = {
  year: number;
  champion: string;
  championTeamId: string;
  teamCount: number;
  draftPicks: number;
  matchups: number;
  transactions: number;
};

/** public/data/seasons/<year>.json */
export type SeasonData = {
  year: number;
  champion: { season: number; team_name: string; provider_team_id: string };
  /** Final order after the playoffs. */
  placements: Placement[];
  /** Regular-season table. */
  standings: TeamResult[];
  managers: SeasonManager[];
  draft: DraftPick[];
  /** Every scheduled game, regular season and playoffs. */
  matchups: Matchup[];
  playoffs: PlayoffGame[];
  lineups: Lineup[];
  transactions: Transaction[];
  settings: Setting[];
  /** Almanac highs: best team week, best player week, best team season. */
  records: SeasonRecord[];
};

export type Placement = { place: number; teamId: string; team: string; manager?: string; summary?: string };

export type TeamResult = {
  rank: number;
  teamId: string;
  team: string;
  wins: number;
  losses: number;
  ties: number;
  winPct: number | null;
  streak: string;
  pointsFor: number;
  pointsAgainst: number;
};

export type SeasonManager = { teamId: string; team: string; manager: string; coManager?: string; moves?: number; trades?: number };

export type DraftPick = {
  overall: number;
  round: number;
  pickInRound: number;
  player: string;
  playerInfo?: string;
  teamId: string;
  team: string;
};

export type TeamScore = { teamId: string; team: string; manager?: string; record?: string; score: number | null };

export type Matchup = { id: string; week: number; teams: TeamScore[] };

export type PlayoffGame = { week: number; label: string; teams: TeamScore[] };

export type PlayerLine = {
  starter: boolean;
  slot: string;
  playerId: string;
  player: string;
  playerInfo?: string;
  opponent?: string;
  points: number | null;
};

export type Lineup = { week: number; requestedTeamId: string; teamId: string; team: string; players: PlayerLine[] };

/** One row of the NFL transaction log; a trade can produce several rows. */
export type Transaction = { date: string; week: number; type: string; players: string; from: string; to: string; by: string };

export type Setting = { label: string; value: string };

export type SeasonRecord = { record_type: string; week?: number; team_name: string; player_name?: string; points: number };

/** public/data/all-time.json */
export type RecordBookData = { managers: BookManager[]; eras: Record<string, Era> };

/** A person; managerId values are surrogate keys such as "manager-07". */
export type BookManager = { id: string; name: string; team: string; label: string; lastSeason: number };

export type Career = {
  managerId: string;
  seasons: number;
  first: number;
  last: number;
  titles: number;
  runnerUp: number;
  topFour: number;
  wins: number;
  losses: number;
  ties: number;
  winPct: number | null;
  firstPlace: number;
  avgRegular: number;
  avgFinal: number | null;
  finalSamples: number;
};

/** A row in the "highs" tables; which point field is set depends on the table. */
export type HighRecord = {
  year: number;
  week?: number;
  team: string;
  managerId: string;
  points?: number;
  pointsFor?: number;
  moves: number;
  trades: number;
  wins: number;
  losses: number;
  ties: number;
};

export type HeadToHead = { managerId: string; opponentId: string; wins: number; losses: number; ties: number };

export type Era = {
  start: number;
  end: number;
  seasonCount: number;
  careers: Career[];
  champions: { year: number; team: string; managerId: string }[];
  highSeasons: HighRecord[];
  highWeeks: HighRecord[];
  headToHead: HeadToHead[];
  verifiedGames: number;
  drafted: { player: string; picks: number }[];
  activity: Record<string, number>;
  mostMoves: HighRecord[];
  mostTrades: HighRecord[];
};
